package com.appnexus.masterdata.product;
import com.appnexus.contracts.workflow.*;
import com.appnexus.contracts.businessobject.*;
import com.appnexus.contracts.businessobject.BusinessObjects.*;
import com.appnexus.platform.tenant.VerifiedTenantContext;
import com.appnexus.masterdata.MasterData;
import java.util.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
/** 商品审核申请接入既有策略、启动和可靠终态交付；完整正文仅留业务库，处理中冻结商品。 */
@Service @ConditionalOnProperty(name="app.workflow.engine.enabled",havingValue="true")
public final class ProductApprovalService implements WorkflowBusiness,Provider {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final ProductV1Service products;private final WorkflowPlatform platform;private final ObjectProvider<WorkflowStarter> starter;private final ObjectProvider<WorkflowTaskAccess> tasks;private final ObjectProvider<BusinessObjectBindings> bindings;
 /** @param jdbc UTC数据源 @param manager 同数据源事务 @param products 商品授权及快照 @param platform 公开身份/组织端口 @param starter 延迟流程启动端口 @param tasks 延迟任务授权端口 @param bindings 公开业务策略解析端口 */
 public ProductApprovalService(JdbcTemplate jdbc,PlatformTransactionManager manager,ProductV1Service products,WorkflowPlatform platform,ObjectProvider<WorkflowStarter> starter,ObjectProvider<WorkflowTaskAccess> tasks,ObjectProvider<BusinessObjectBindings> bindings){this.jdbc=jdbc;this.tx=new TransactionTemplate(manager);this.products=products;this.platform=platform;this.starter=starter;this.tasks=tasks;this.bindings=bindings;}
 private static final List<Field> FIELDS=List.of(new Field("productVersion","商品版本","Product version","NUMBER","",true));
 private static final Operation SUBMIT=new Operation("submit","提交商品审核","Submit product approval","masterdata.product:submit_approval","ProductApproval.submit",new PageOperation("master-data/product","/master-data/product","商品档案","Products","POST","/api/master-data/product/{id}/approval"),List.of(),new InteractionContract("ProductApproval.submit",1,"ProductApproval","submit","提交商品审核","Submit product approval",InteractionContract.Trigger.USER_ACTION,List.of(new InteractionContract.Capability(InteractionContract.Service.WORKFLOW,InteractionContract.Completion.CALLBACK,"productApproval","approval",FIELDS,Set.of("APPROVED","REJECTED","WITHDRAWN"),"product.approval",1))));
 @Override public Descriptor descriptor(){return new Descriptor("ProductApproval","商品审核申请","Product approval","master-data",1,Category.TRANSACTION,FIELDS,List.of(SUBMIT));}
 @Override public Capability capability(){return new Capability("productApproval","商品审核","masterdata.product:submit_approval","/master-data/product",Set.of(),Set.of("productVersion"));}
 /** 当前账号有效任职组织，用于选择审批路由，不开放自由组织ID。 */
 public Object organizations(WorkflowContext c){return platform.documentOrganizations(c);}
 /** 提交固定商品版本，完整性不足拒绝；流程配置缺失整单回滚，不伪造审批。 */
 public Object submit(VerifiedTenantContext c,WorkflowContext w,String product,long version,String organization){if(!platform.allowed(w,"masterdata.product:submit_approval")||!platform.allowed(w,"masterdata.product:read"))throw new MasterData.Rejection(403,"MASTER_DATA_DENIED");UUID.fromString(organization);if(platform.documentOrganizations(w).stream().noneMatch(o->o.id().equalsIgnoreCase(organization)))throw new MasterData.Rejection(409,"PRODUCT_APPROVAL_ORGANIZATION_INVALID");return tx.execute(s->{var lock=jdbc.queryForMap("SELECT status,version,structure_state,draft_archived_at FROM md_product_v1 WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?) FOR UPDATE",w.tenantId(),product);var prior=jdbc.queryForList("SELECT BIN_TO_UUID(id) id,BIN_TO_UUID(product_id) productId,product_version,instance_id instanceId,BIN_TO_UUID(organization_id) organization FROM md_product_approval WHERE tenant_id=UUID_TO_BIN(?) AND applicant_id=UUID_TO_BIN(?) AND request_key=UUID_TO_BIN(?)",w.tenantId(),w.actorId(),w.requestId());if(!prior.isEmpty()){var r=prior.getFirst();if(!product.equals(r.get("productId"))||((Number)r.get("product_version")).longValue()!=version+1||!organization.equals(r.get("organization")))throw new MasterData.Rejection(409,"PRODUCT_APPROVAL_KEY_REUSED");return Map.of("id",r.get("id"),"instanceId",r.get("instanceId"),"version",version+1);}
products.ensureNotInApproval(c,product);var before=products.extensionSnapshot(c,product);if(((Number)lock.get("version")).longValue()!=version||"ENABLED".equals(lock.get("status"))||lock.get("draft_archived_at")!=null||!"COMPLETE".equals(lock.get("structure_state")))throw new MasterData.Rejection(409,"PRODUCT_APPROVAL_NOT_READY");products.requireCompleteForApproval(c,product);String id=UUID.randomUUID().toString();long frozen=version+1;jdbc.update("UPDATE md_product_v1 SET version=version+1,updated_by=UUID_TO_BIN(?),updated_at=CURRENT_TIMESTAMP(6) WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)",w.actorId(),w.tenantId(),product);jdbc.update("INSERT INTO md_product_approval(id,tenant_id,product_id,request_key,product_version,applicant_id,organization_id,basis_snapshot,created_by,updated_by) VALUES(UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),UUID_TO_BIN(?),?,UUID_TO_BIN(?),UUID_TO_BIN(?),?,UUID_TO_BIN(?),UUID_TO_BIN(?))",id,w.tenantId(),product,w.requestId(),frozen,w.actorId(),organization,new tools.jackson.databind.ObjectMapper().writeValueAsString(products.extensionSnapshot(c,product)),w.actorId(),w.actorId());var context=new Context(w.tenantId(),w.actorId(),w.requestId());bindings.getObject().verifyPageOperation(context,"ProductApproval","submit","ProductApproval.submit");var resolved=bindings.getObject().resolveOperation(context,"ProductApproval","submit",id,frozen,Map.of("productVersion",String.valueOf(frozen)));if(!"WORKFLOW".equals(resolved.service()))throw new MasterData.Rejection(409,"PRODUCT_APPROVAL_WORKFLOW_REQUIRED");String instance=starter.getObject().startBound(w,"ProductApproval",id,frozen,organization,"approval","productApproval",resolved.id());jdbc.update("UPDATE md_product_approval SET instance_id=?,resolution_id=? WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)",instance,resolved.id(),w.tenantId(),id);products.extensionEvent(c,product,"APPROVAL_SUBMIT",before);return Map.of("id",id,"instanceId",instance,"version",frozen);});}
 /** 原商品读取权内审核历史；不将申请UUID作为数据授权。 */
 public Object list(VerifiedTenantContext c,String product){products.read(c,product);return jdbc.queryForList("SELECT BIN_TO_UUID(id) id,product_version productVersion,state,instance_id instanceId,created_at createdAt,updated_at updatedAt FROM md_product_approval WHERE tenant_id=UUID_TO_BIN(?) AND product_id=UUID_TO_BIN(?) ORDER BY created_at DESC",c.tenantId().toString(),product);}
 @Override public Map<String,String> snapshot(Invocation i){var row=checked(i,false);if(i.workflow()==null){if(!platform.allowed(i.context(),"masterdata.product:submit_approval")||!i.context().actorId().equals(row.get("applicant")))throw new SecurityException("PRODUCT_APPROVAL_DENIED");}else if(!permitted(i))throw new SecurityException("PRODUCT_APPROVAL_TASK_DENIED");return Map.of("productVersion",String.valueOf(row.get("product_version")));}
 /** 节点办理只复核任务；仅带匹配终态实例的EXECUTE可靠交付可写审核结果，同调用幂等。 */
 @Override public Result execute(Invocation i){return tx.execute(s->{var row=checked(i,true);if("WITHDRAW".equals(i.operation())){if(!i.context().actorId().equals(row.get("applicant"))||i.workflow()==null||!Objects.equals(row.get("instance_id"),i.workflow().instanceId()))throw new SecurityException("PRODUCT_APPROVAL_DENIED");return new Result(false,Map.of());}if(!"EXECUTE".equals(i.operation())){if(!Set.of("APPROVE","REJECT").contains(i.operation())||!permitted(i)||!i.values().isEmpty())throw new SecurityException("PRODUCT_APPROVAL_TASK_DENIED");return new Result(false,Map.of());}var ref=i.workflow();if(ref==null||!"APPROVAL".equals(ref.mode())||!Objects.equals(row.get("instance_id"),ref.instanceId())||!Objects.equals(row.get("applicant"),i.context().actorId())||!Set.of("APPROVED","REJECTED","WITHDRAWN").contains(ref.result()))throw new SecurityException("PRODUCT_APPROVAL_RESULT_DENIED");if(!"SUBMITTED".equals(row.get("state"))){if(!Objects.equals(row.get("delivery_id"),i.invocationId())||!Objects.equals(row.get("state"),ref.result()))throw new SecurityException("PRODUCT_APPROVAL_RESULT_CONFLICT");return new Result(false,Map.of());}jdbc.update("UPDATE md_product_approval SET state=?,delivery_id=?,updated_by=UUID_TO_BIN(?),updated_at=CURRENT_TIMESTAMP(6) WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)",ref.result(),i.invocationId(),i.context().actorId(),i.context().tenantId(),i.objectId());return new Result(false,Map.of());});}
 /** 审批原文只允许原申请人或当前有效任务持有人；结束任务不保留快照读取授权。 */
 public Object detail(WorkflowContext c,String id,String task){var rows=jdbc.queryForList("SELECT BIN_TO_UUID(id) id,BIN_TO_UUID(product_id) productId,product_version productVersion,BIN_TO_UUID(applicant_id) applicant,BIN_TO_UUID(organization_id) organization,state,CAST(basis_snapshot AS CHAR) snapshot,instance_id instanceId FROM md_product_approval WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)",c.tenantId(),id);if(rows.size()!=1||!platform.active(c.tenantId(),c.actorId()))throw new MasterData.Rejection(403,"MASTER_DATA_DENIED");var row=rows.getFirst();boolean own=Objects.equals(row.get("applicant"),c.actorId())&&platform.allowed(c,"masterdata.product:read");if(!own&&!tasks.getObject().permits(c,task,"ProductApproval",id,((Number)row.get("productVersion")).longValue(),"productApproval","productVersion",false))throw new MasterData.Rejection(403,"MASTER_DATA_DENIED");return Map.of("state",row.get("state"),"productVersion",row.get("productVersion"),"snapshot",new tools.jackson.databind.ObjectMapper().readTree((String)row.get("snapshot")));}
 private boolean permitted(Invocation i){return platform.active(i.context().tenantId(),i.context().actorId())&&tasks.getObject().permits(i.context(),i.taskId(),"ProductApproval",i.objectId(),i.objectVersion(),"productApproval","productVersion",false);}
 private Map<String,Object> checked(Invocation i,boolean lock){if(!"ProductApproval".equals(i.objectType())||!platform.active(i.context().tenantId(),i.context().actorId()))throw new SecurityException("PRODUCT_APPROVAL_DENIED");var rows=jdbc.queryForList("SELECT *,BIN_TO_UUID(applicant_id) applicant,BIN_TO_UUID(organization_id) organization FROM md_product_approval WHERE tenant_id=UUID_TO_BIN(?) AND id=UUID_TO_BIN(?)"+(lock?" FOR UPDATE":""),i.context().tenantId(),i.objectId());if(rows.size()!=1)throw new SecurityException("PRODUCT_APPROVAL_DENIED");var r=rows.getFirst();if(!"EXECUTE".equals(i.operation())&&!"SUBMITTED".equals(r.get("state")))throw new IllegalArgumentException("PRODUCT_APPROVAL_STATE_CHANGED");if(((Number)r.get("product_version")).longValue()!=i.objectVersion()||!Objects.equals(r.get("organization"),i.organizationId()))throw new IllegalArgumentException("PRODUCT_APPROVAL_BASIS_CHANGED");return r;}
}
